/* Physical units: each head is 1, then one tick every 12/60 seconds. Fake notes are 0. */
'use strict';
(function(root){
const C=root.DCCore,EPS=1e-9,beat=v=>Array.isArray(v)?C.beatValue(v):Number(v);
const value=n=>n<=BigInt(Number.MAX_SAFE_INTEGER)?Number(n):n.toString();
function options(){return{model:'duration',holdFrames:12};}
function clock(ch){const nodes=[{beat:0,bpm:Number(ch.bpm)||120,time:0}];for(const t of ch.timings||[]){const previous=nodes.at(-1);nodes.push({beat:Number(t.beat),bpm:Number(t.bpm),time:previous.time+(Number(t.beat)-previous.beat)*60/previous.bpm});}const raw=beat=>{let lo=0,hi=nodes.length;while(lo<hi){const mid=(lo+hi)>>>1;if(nodes[mid].beat<=beat)lo=mid+1;else hi=mid;}const n=nodes[Math.max(0,lo-1)];return n.time+(beat-n.beat)*60/n.bpm;};return{raw,shift:raw(Number(ch.audioBeat)||0)+(Number(ch.offset)||0)/1000};}
function records(ch){const out=[],add=(start,end,weight=1,slide=false)=>{start=beat(start);end=end===null||end===undefined?null:beat(end);if(!slide&&end===start)return;out.push({beat:start,end,weight:BigInt(weight)});};if(ch.events&&!Array.isArray(ch.shownotes)){const chains=new Map();for(const e of ch.events){if(e.kind==='unknown')continue;for(const position of e.positions||[]){if(e.kind!=='slide'){add(e.beat,e.end);continue;}const key=(e.chainId||e.id)+':'+position,previous=chains.get(key);if(previous){previous.end=e.end;}else{const item={beat:e.beat,end:e.end,weight:e.stack??1};chains.set(key,item);}}}for(const n of chains.values())add(n.beat,n.end,n.weight,true);return out;}for(const n of ch.notes||[])add(n.beat,n.end);for(const n of ch.shownotes||[])if(n.kind==='slide')add(n.beat,n.segments.at(-1).end,n.stack??1,true);else add(n.beat,n.end);return out;}
function upper(list,time,key){let lo=0,hi=list.length;while(lo<hi){const mid=(lo+hi)>>>1;if(key(list[mid])<=time+EPS)lo=mid+1;else hi=mid;}return lo;}
function prefix(list,weight){const out=[0n];for(const n of list)out.push(out.at(-1)+weight(n));return out;}
class UnitIndex{
 constructor(chart,prefs={}){this.policy=options(prefs);const timer=clock(chart);this.shift=timer.shift;this.items=records(chart).map(n=>({...n,startRaw:timer.raw(n.beat),endRaw:n.end===null?null:timer.raw(n.end)})).map(n=>({...n,time:n.startRaw-timer.shift,endTime:n.endRaw===null?null:n.endRaw-timer.shift})).sort((a,b)=>a.time-b.time);this.headPrefix=prefix(this.items,n=>n.weight);this.holds=this.items.filter(n=>n.endTime!==null&&n.endTime>n.time);for(const n of this.holds)n.ticks=this.ticks(n,n.endRaw);this.finished=this.holds.slice().sort((a,b)=>a.endTime-b.endTime);this.finishPrefix=prefix(this.finished,n=>BigInt(n.ticks)*n.weight);this.totalBig=this.headPrefix.at(-1)+this.finishPrefix.at(-1);this.total=value(this.totalBig);let size=1;while(size<this.holds.length)size*=2;this.size=size;this.maxEnd=new Float64Array(size*2);this.maxEnd.fill(-Infinity);for(let i=0;i<this.holds.length;i++)this.maxEnd[size+i]=this.holds[i].endTime;for(let i=size-1;i>0;i--)this.maxEnd[i]=Math.max(this.maxEnd[i*2],this.maxEnd[i*2+1]);}
 ticks(n,raw){return Math.max(0,Math.floor(Math.max(0,Math.min(raw,n.endRaw)-n.startRaw)/.2+EPS));}
 at(time){if(Number.isNaN(Number(time)))return 0;time=Number(time);if(time===Infinity)return this.total;let sum=this.headPrefix[upper(this.items,time,n=>n.time)]+this.finishPrefix[upper(this.finished,time,n=>n.endTime)];const visit=(node,left,right)=>{if(this.maxEnd[node]<=time+EPS||left>=this.holds.length||this.holds[left].time>time+EPS)return;if(right-left===1){const n=this.holds[left];sum+=BigInt(this.ticks(n,time+this.shift))*n.weight;return;}const mid=(left+right)>>>1;visit(node*2,left,mid);visit(node*2+1,mid,right);};if(this.holds.length)visit(1,0,this.size);return value(sum);}
}
function index(chart,prefs){return new UnitIndex(chart,prefs);}
function total(chart,prefs){return index(chart,prefs).total;}
root.DCUnits={UnitIndex,index,total,records,clock,options,value};
})(typeof window==='undefined'?globalThis:window);
